_WHITESPACE = " \t\r\f\v"


def parse(input_string):
    if not input_string.startswith("("):
        raise ValueError("tree missing")
    end = _find_tree_end(input_string, 0)
    return _parse_tree(input_string[: end + 1])


def _parse_tree(s):
    inner = s[1:-1]
    if not inner.startswith(";"):
        raise ValueError("tree with no nodes")
    return _parse_node(inner)


def _parse_node(s):
    properties = {}
    children = []
    i = 1  # skip the leading ';'
    while i < len(s):
        c = s[i]
        if c == "(":
            end = _find_tree_end(s, i)
            children.append(_parse_tree(s[i : end + 1]))
            i = end + 1
        elif c == ";":
            break  # next sibling node
        else:
            key, values, i = _parse_property(s, i)
            properties[key] = values
    return SgfTree(properties=properties, children=children)


def _parse_property(s, i):
    j = s.find("[", i)
    if j == -1:
        raise ValueError("properties without delimiter")
    key = s[i:j]
    if not key.isupper():
        raise ValueError("property must be in uppercase")
    values = []
    while j < len(s) and s[j] == "[":
        end = _find_value_end(s, j)
        values.append(_decode_value(s[j + 1 : end]))
        j = end + 1
    return key, values, j


def _find_tree_end(s, start):
    """Index of the ')' matching the '(' at s[start], ignoring parens inside values."""
    depth = 0
    in_value = False
    i = start
    while i < len(s):
        c = s[i]
        if in_value:
            if c == "\\" and i + 1 < len(s):
                i += 2
                continue
            if c == "]":
                in_value = False
        elif c == "[":
            in_value = True
        elif c == "(":
            depth += 1
        elif c == ")":
            depth -= 1
            if depth == 0:
                return i
        i += 1
    raise ValueError("tree missing")


def _find_value_end(s, start):
    """Index of the ']' closing the value that starts at s[start] == '['."""
    i = start + 1
    while i < len(s):
        c = s[i]
        if c == "\\" and i + 1 < len(s):
            i += 2
            continue
        if c == "]":
            return i
        i += 1
    raise ValueError("unexpected end of value")


def _decode_value(s):
    out = []
    i = 0
    while i < len(s):
        c = s[i]
        if c == "\\" and i + 1 < len(s):
            nxt = s[i + 1]
            if nxt == "\n":
                pass  # escaped newline is removed entirely
            elif nxt in _WHITESPACE:
                out.append(" ")
            else:
                out.append(nxt)
            i += 2
        elif c == "\n":
            out.append("\n")
            i += 1
        elif c in _WHITESPACE:
            out.append(" ")
            i += 1
        else:
            out.append(c)
            i += 1
    return "".join(out)

