def _parse_tree(s):
    inner = s[1:-1]
    if not inner.startswith(";"):
        raise ValueError("tree with no nodes")
    tree, _ = _parse_node(inner, 0)
    return tree


def _parse_node(s, i):
    """Parse one node starting at s[i] == ';'; returns (node, index after it)."""
    properties = {}
    children = []
    i += 1
    while i < len(s):
        c = s[i]
        if c == "(":
            end = _find_tree_end(s, i)
            children.append(_parse_tree(s[i : end + 1]))
            i = end + 1
        elif c == ";":
            child, i = _parse_node(s, i)
            children.append(child)
        else:
            key, values, i = _parse_property(s, i)
            properties[key] = values
    return SgfTree(properties=properties, children=children), i
